    return hmac.compare_digest(sign(body, secret), signature)


def _subscribed(endpoint: Endpoint, name: str) -> bool:
    return name in endpoint.events or f"{name.split('.', 1)[0]}.*" in endpoint.events


def _mask_card_numbers(value):
    """Return a copy of event data with any ``card_number`` field masked via redact_pan.

    Dicts and lists are traversed and rebuilt so the caller's payload is not mutated;
    any other value is returned as-is.
    """
    if isinstance(value, dict):
        masked = {}
        for key, val in value.items():
            if key == "card_number" and isinstance(val, str):
                masked[key] = redact_pan(val)
            else:
                masked[key] = _mask_card_numbers(val)
        return masked
    if isinstance(value, list):
        return [_mask_card_numbers(item) for item in value]
    return value


